def detail_markdown(s):
    import re
    from html import unescape
    s=re.sub(r'<a class="citation"[^>]*>\[(\d+)\]</a>',r'[\1]',s)
    s=re.sub(r'<img[^>]*src="([^"]+)"[^>]*alt="([^"]*)"[^>]*>',r'![\2](../\1)',s)
    s=re.sub(r'<h[34][^>]*>(.*?)</h[34]>',r'\n\n### \1\n\n',s)
    s=s.replace('</p>','\n\n').replace('</li>','\n').replace('<li>','- ').replace('</article>','\n\n')
    text=unescape(re.sub(r'<[^>]+>','',s))
    text='\n'.join(line.strip() for line in text.splitlines())
    return re.sub(r'\n{3,}', '\n\n', text).strip()

# Plain Markdown notes provide a readable entry inside GitHub as well as the website.
def strip(s):
    import re
    from html import unescape
    s=re.sub(r'<a class="citation"[^>]*>\[(\d+)\]</a>',r'[\1]',s)
    s=re.sub(r'<img[^>]*src="([^"]+)"[^>]*alt="([^"]*)"[^>]*>',r'![\2](../\1)',s)
    s=s.replace('</p>','<br>').replace('<p>','').replace('<b>','**').replace('</b>','**')
    return unescape(re.sub(r'<(?!br\b)[^>]*>','',s))
docs=ROOT/'docs';docs.mkdir(exist_ok=True)
(docs/'ITERATION.md').write_text('# Why five probes became two\n\n'+'\n\n'.join('## '+t+'\n\n'+s for _,t,s in TIMELINE)+'\n\n## Selection criterion\n\nReduce barriers of knowledge, language, manual skill, arriving alone and willingness to use AI. Pilot sessions help us identify where people need another way to join.\n\nKeep 1 as an introduction. Develop 2 as A. Pause 3. Merge 4 and 5 as B.\n\n[Full five-probe table](COMPARISON.md) · [A](PROBE_A.md) · [B](PROBE_B.md)\n',encoding='utf-8')
(docs/'COMPARISON.md').write_text('# Five-probe evaluation and initial selection\n\nOne continuous table links the activity, question, theory, speculation, feedback and decision. The table records the reasons for choosing and refining the activities.\n\n| '+' | '.join(HEADERS)+' |\n| '+' | '.join('---' for _ in HEADERS)+' |\n'+''.join('| '+' | '.join(strip(c).replace('|',' / ') for c in row)+' |\n' for row in ROWS)+'\n\n[Original speculation passages](SPECULATION.md) · [Numeric references](SOURCES.md)\n',encoding='utf-8')
for d in DIRECTIONS:
    md=f'# Direction {d["letter"]} · {d["title"]}\n\n{d["origin"]}. {d["time"]} is an estimate.\n\n{d["sentence"]}\n\n## Research question\n\n{d["rq"]}\n\n{d["purpose"]}\n\n## Visitor activity\n\n'
    md+='\n\n'.join(f'{i}. **{t}.** {s}' for i,(t,s) in enumerate(d['steps'],1))
    for title,key in [('AI’s role','ai'),('The non-AI route','noai'),('Smallest working set-up','setup'),('Broad participation','broad')]:md+=f'\n\n## {title}\n\n{d[key]}'
    md+='\n\n## Theory and HCI\n\n'+'\n\n'.join(f'**{t}.** {s} '+ ' '.join(f'[{n}]' for n in rr) for t,s,rr in d['theory'])
    for title,key in [('Speculative scenario','future'),('Where speculation enters','speculation'),('Participant input and data','record'),('Analysis','analysis'),('Candidate contribution','value'),('Revision criterion','checkpoint')]:md+=f'\n\n## {title}\n\n{d[key]}'
    md+='\n\n## Illustrated implementation guide\n\n'+detail_markdown(extra_detail(d))+'\n'
    if d['id']=='a':md+='\n\n[Detailed Huayao evidence and reasoning for A](EVIDENCE_FOR_A.md)\n'
    md+='\n\n[Original speculation passages](SPECULATION.md) · [Numeric references](SOURCES.md)\n'
    (docs/f'PROBE_{d["letter"]}.md').write_text(md,encoding='utf-8')
(docs/'SPECULATION.md').write_text('# Speculation · Original passages and design reasoning\n\nDunne and Raby (2013), Speculative Everything [21]. Printed book pages. Footnote markers omitted. Interpretations and applications are ours. Credited book figure crops appear in the website table and beside the case quotations. The future situation and the activity props give visitors a concrete change to discuss.\n\n'+''.join(f'## Passage {q["number"]} · {q["title"]}\n\n{q.get("creator","")}{". " if q.get("creator") else ""}{q.get("case_description","")}\n\n> {q["original"]}\n\nChapter {q["chapter"]}, pp. {q["pages"]}.\n\n**The idea we take from it.** {q["meaning"]}\n\n**How it changes the activity.** {q["application"]}\n\n' for q in QUOTES)+'[Numeric references](SOURCES.md)\n',encoding='utf-8')
(docs/'SOURCES.md').write_text('# Numeric references\n\nMain search cut-off 14 October 2026. Targeted material-interaction and practice checks added 16 October 2026. Original passages and figures checked 16 October 2026. Focused evidence synthesis, not a systematic review.\n\n'+''.join(f'{r["number"]}. {r["title"]} [Source]({r["url"]})\n\n   Reading scope: {r.get("reading_scope","")}\n\n' for r in SOURCES)+'Paper image licences and original figure numbers are in [the figure credits](../data/figure-credits.json). Figure crops do not change their content. Related Huayao studies are not independent replications. ZOMA and the empathy paper are used at abstract level.\n',encoding='utf-8')
